use crate::{guidance::{names,visit_boards},model::GameData};
use serde_json::{json,Map,Value};
use std::collections::BTreeSet;
const NOTE:&str="Average fraction of this champion's own non-unique trait tiers activated. This is not damage efficiency, carry strength, total buffs or a win probability. Teamwide and conditional effects are not converted into percentages.";
pub fn annotate_trait_support(result:&mut Value,data:&GameData)->Result<(),String>{let mut collab:BTreeSet<String>=result["collab_pool"].as_array().map(|a|a.iter().filter_map(Value::as_str).map(str::to_owned).collect()).unwrap_or_default();collab.insert("Sona".into());let band=result["sona_band"].as_str().unwrap_or("").to_owned();visit_boards(result,&mut |board|{let mut support=Map::new();for name in names(board){let champion=data.champions.get(&name).ok_or_else(||format!("Unknown champion: {name}"))?;let mut memberships:BTreeSet<_>=champion.traits.iter().filter(|t|t.as_str()!="Collab").cloned().collect();if collab.contains(&name){memberships.insert("Collab".into());}if name=="Sona"&&!band.is_empty(){memberships.insert(band.clone());}let mut details=vec![];let mut fractions=vec![];for t in memberships{let def=data.traits.get(&t).ok_or_else(||format!("Unknown trait: {t}"))?;let count=board["traits"].as_array().and_then(|a|a.iter().find(|r|r["name"].as_str()==Some(t.as_str()))).and_then(|r|r["count"].as_u64()).unwrap_or(0) as usize;let tier=def.breakpoints.partition_point(|p|*p<=count);if !def.unique{fractions.push(tier as f64/def.breakpoints.len() as f64)}details.push(json!({"name":t,"count":count,"reached":if tier>0{def.breakpoints[tier-1]}else{0},"tier_index":tier,"max_tiers":def.breakpoints.len(),"unique":def.unique,"effect":def.description}));}let percent=if fractions.is_empty(){Value::Null}else{json!((1000.0*fractions.iter().sum::<f64>()/fractions.len() as f64).round_ties_even()/10.0)};support.insert(name,json!({"percent":percent,"metric":"personal_trait_tier_completion","details":details,"note":NOTE}));}board["champion_trait_support"]=Value::Object(support);Ok(())})}
